 if($username===''||$password===''){$err='Username and password are required.';}else{$u=$model->findByUsername($username);if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'username'=>$u['username'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];if(!empty($_POST['remember'])){setcookie('remember_username',$username,['expires'=>time()+2592000,'path'=>'/','httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']);}redirect_to(project_base_url().'/index.php');}else{$err='Invalid username or password, or the account is inactive.';}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · StockFlow</title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="auth"><div class="auth-box"><div class="auth-logo"><span class="brand-mark">S</span><div><h1>Stock<span class="brand-accent">Flow</span></h1><div class="muted auth-sub">Inventory & Stock Management System</div></div></div><div class="notice neutral"><b>Secure Login</b><br><span class="muted">Sign in to open your role-specific dashboard.</span></div><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><form method="post" autocomplete="on" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label for="username">Username</label><input id="username" name="username" required minlength="3" value="<?=e($_COOKIE['remember_username']??'')?>" placeholder="Enter username"></div><div class="field"><label for="password">Password</label><input id="password" type="password" name="password" required placeholder="Enter password"></div><label class="checkbox-row"><input type="checkbox" name="remember"> Remember my username</label><button class="btn" type="submit">Sign In</button></form><p class="helper" style="margin-top:16px">Don’t have an account? <a class="link" href="register.php">Sign Up</a></p><p class="helper">Use the demo credentials listed in README.md.</p></div></div><script src="assets/js/app.js"></script></body></html>
